function pushMenu(title,a,b,opts){
  // Supports pushMenu(title, items, opts) and pushMenu(title, sub, items, opts)
  let sub, items;
  if(Array.isArray(a)){ items=a; opts=b||{}; sub=opts.sub||""; }
  else { sub=a; items=b; opts=opts||{}; }
  opts=opts||{};
  // Normalize: items may be an array (static) or a builder function (fresh every render)
  if(typeof items!=="function") items=(function(arr){ return function(){ return arr; }; })(items);
  menus.push({title:title,sub:sub,items:items,view:opts.view||null,sel:opts.sel||0});
  renderAll();
}

