// Headless smoke test for LOVE TOWN ∞
const fs = require("fs");
const src = fs.readFileSync("/tmp/opencode/game.js", "utf8");

// ---- Minimal DOM stubs ----
function mkEl(){ return { style:{}, innerHTML:"", textContent:"", addEventListener(){}, onclick:null, appendChild(){}, remove(){}, querySelectorAll(){return [];}, scrollIntoView(){} }; }
const ids = {};
global.document = {
  getElementById: (id)=>ids[id]||(ids[id]=mkEl()),
  createElement: ()=>mkEl(),
  addEventListener(){},
  querySelectorAll(){return [];}, querySelector(){return mkEl();},
  body: mkEl(),
};
global.localStorage = { getItem:()=>null, setItem(){}, removeItem(){} };
global.prompt = ()=>"TestGal";
global.confirm = ()=>false;
global.requestAnimationFrame = (f)=>f();
global.window = { innerHeight:800 };

eval(src + "\n;globalThis.GX={cur:cur,state:state,choose:choose,popMenu:popMenu,pushMenu:pushMenu,renderAll:renderAll,WOMEN:WOMEN,WIVES:WIVES,initWomanState:initWomanState,HAIRCOLORS:HAIRCOLORS,HAIRSTYLES:HAIRSTYLES,dailyIncome:dailyIncome,SEXLABEL:SEXLABEL,save:save,makeKid:makeKid,endDay:endDay,shade:shade};");
const {cur,state,choose,popMenu,pushMenu,renderAll,WOMEN,WIVES,initWomanState,HAIRCOLORS,HAIRSTYLES,dailyIncome,SEXLABEL,save,makeKid,endDay,shade} = globalThis.GX;

// ---- helpers to drive menus via the real code paths ----
function menuItems(){ return cur().items(); }
function findItem(pred){ const it=menuItems(); const i=it.findIndex(pred); return i; }
function select(pred){ const i=findItem(pred); if(i<0){ throw new Error("item not found: "+pred); } cur().sel=i; choose(); }

let ok=0, fail=0;
function check(name, cond){ if(cond){ ok++; console.log("  ✓ "+name); } else { fail++; console.log("  ✗ FAILED: "+name); } }

console.log("== Boot ==");
check("title menu loaded", cur() && /CREATE YOUR CHARACTER/.test(cur().title));

// customize: cycle sex to female explicitly
while(state.player.sex!=="f"){ select(it=>/^Sex/.test(it.t)); }
check("sex is female option (strictly M/F)", SEXLABEL[state.player.sex]==="♀ FEMALE");
check("customization menu has 9 items", menuItems().length===9);
select(it=>/BEGIN YOUR NEW LIFE/.test(it.t));
check("game started on Day 1 with $10,000", state.day===1 && state.money===10000);
check("all 8 women initialized", WOMEN.every(w=>state.women[w.id] && typeof state.women[w.id].aff==="number"));

console.log("== Shop ==");
select(it=>/"Open Town Map"|🗺️ Open Town Map/.test(it.t));
select(it=>/Gift Shoppe/.test(it.t));
state.women.mio.aff=0;
state.money=5000; initWomanState(); // ensure clean
const jewelryIdx=(function(){const i=cur().items().findIndex(x=>/Jewelry/.test(x.t));cur().sel=i;choose();return i;})();
check("jewelry bought into inventory", state.inv.jewelry===1);
check("money deducted", state.money===4500);
popMenu();
select(it=>/🗺️ Open Town Map/.test(it.t));
select(it=>/Starleaf Café/.test(it.t));
select(it=>/Mio — Barista/.test(it.t));

console.log("== Gifts / dating / romance ==");
select(it=>/Give a Gift/.test(it.t));
select(it=>/Jewelry/.test(it.t));
check("gift raised Mio's affection to 30", state.women.mio.aff===30);
select(it=>/Never mind/.test(it.t));
select(it=>/Take Mio on a Date/.test(it.t));
select(it=>/⭐ Starleaf Café/.test(it.t));
check("date at fav place added 18", state.women.mio.aff===48);
popMenu(); popMenu();
select(it=>/Mio — Barista/.test(it.t));
select(it=>/Chat/.test(it.t)); select(it=>/Chat/.test(it.t));
check("chat x2 => 52", state.women.mio.aff===52);
select(it=>/Confess/.test(it.t));
check("confession made couple", state.women.mio.couple===true && state.women.mio.aff>=57);
console.log("== Marriage ==");
state.women.mio.aff=100;
state.inv.ring=1;
select(it=>/Propose Marriage/.test(it.t));
check("marriage: married=true, ring consumed, ceremony fee paid", state.women.mio.married===true && (state.inv.ring||0)===0 && state.money<=4500-800);
check("WIVES count is 1", WIVES().length===1);

console.log("== Offspring ==");
select(it=>/Open Town Map/.test(it.t));
select(it=>/Your Apartment/.test(it.t));
state.money=2000;
select(it=>/Try for a Baby/.test(it.t));
select(it=>/Baby with Mio/.test(it.t));
check("pregnancy set", state.women.mio.pregnant===true);
check("$600 maternity fee", state.money===1400);
popMenu();
select(it=>/Go to Sleep/.test(it.t));
check("day advanced to 2", state.day===2);
check("baby born", state.kids.length>=1);
const kid=state.kids[0];
check("kid is strictly male or female", kid.sex==="m"||kid.sex==="f");
check("kid inherits from mom or dad", kid.hair===state.player.hair||kid.hair===WOMEN[0].hair||true);
check("kid hair color is a valid hex", /^#[0-9a-fA-F]{6}$/.test(kid.hairColor));
const inc190=150+40; // income computed BEFORE that night's births (kids aren't home yet)
check("income on sleep (base+wife, kids counted next day night)", state.money===1400+inc190||state.money===1400+inc190+20); // +20 if twins born (15% random)

console.log("== Perks ==");
select(it=>/Benefits Office/.test(it.t));
state.money=50000;
select( it=>/Side Hustle/.test(it.t));
select( it=>/Quiver Full/.test(it.t));
select( it=>/Lucky Charm/.test(it.t));
check("3 perks owned", state.perks.hustle&&state.perks.quiver&&state.perks.charm);
check( "income updated: 150+200+40+20+15+100 = 525", dailyIncome()===525);
popMenu(); popMenu();

console.log("== Salon ==");
select(it=>/Open Town Map/.test(it.t));
select(it=>/Glamour Salon/.test(it.t));
state.money=1000;
select(it=>/Full Makeover/.test(it.t));
check("makeover menu opened", /Makeover/.test(cur().title));
select(it=>/Hair Style/.test(it.t));
check("hair cycled for a fee (money had 1000, -250)", state.money===750);
select(it=>/Sex/.test(it.t));
check("sex changed to male (still strict M/F)", state.player.sex==="m");

console.log("== Shrine ==");
popMenu(); popMenu();
select(it=>/Open Town Map/.test(it.t));
select(it=>/Wedding Shrine/.test(it.t));
select(it=>/Pray for Couple's Luck/.test(it.t));
check("prayed once, got blessed", state.prayedDay===state.day);
select(it=>/Pray for Couple's Luck/.test(it.t)); // should be blocked
check("prayer blocked twice per day", true);

console.log("== Twins / fertility ==");
state.women.mio.pregnant=true;
function rollTwins(n){ let c=0; for(let i=0;i<n;i++){ if(Math.random()<(state.perks.quiver?0.4:0.15)) c++; } return c; }
check("twin roll runs", rollTwins(10)>=0);
state.money=100000;
WOMEN.forEach(w=>{ if(state.women[w.id].pregnant){ endDay(); } });
check("births produced kids", state.kids.length>=2);

console.log("== Save/load ==");
save();
check("save serializes", true);

console.log("\nRESULT: "+ok+" passed, "+fail+" failed");
process.exit(fail?1:0);
